const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.navlinks');
if(toggle&&nav){toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Fermer':'Menu';nav.classList.toggle('open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='Menu';}});}
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const search=document.querySelector('#article-search');
if(search){const cards=[...document.querySelectorAll('[data-article]')],chips=[...document.querySelectorAll('[data-filter]')],count=document.querySelector('#result-count'),empty=document.querySelector('#no-results'),pages=document.querySelector('#pagination');let category='all',page=1;const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function render(){const query=normalize(search.value).trim();const matching=cards.filter(c=>(category==='all'||c.dataset.category===category)&&normalize(c.textContent).includes(query));cards.forEach(c=>c.hidden=true);matching.slice((page-1)*12,page*12).forEach(c=>c.hidden=false);count.textContent=`${matching.length} article${matching.length===1?'':'s'}`;empty.hidden=matching.length>0;pages.replaceChildren();for(let i=1;i<=Math.ceil(matching.length/12);i++){const b=document.createElement('button');b.textContent=i;b.setAttribute('aria-label',`Page ${i}`);if(i===page)b.setAttribute('aria-current','page');b.addEventListener('click',()=>{page=i;render();document.querySelector('#articles').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});pages.querySelector('[aria-current="page"]')?.focus({preventScroll:true});});pages.append(b);}}
search.addEventListener('input',()=>{page=1;render();});chips.forEach(chip=>chip.addEventListener('click',()=>{category=chip.dataset.filter;page=1;chips.forEach(c=>c.setAttribute('aria-pressed',String(c===chip)));render();}));render();}
